package com.morrowshop.service;
import com.morrowshop.config.MyBatisProvider;import com.morrowshop.domain.*;import com.morrowshop.mapper.*;import java.math.BigDecimal;import java.util.*;import org.apache.ibatis.session.SqlSession;
public class OrderService {
 public String checkout(long userId){try(SqlSession s=MyBatisProvider.getFactory().openSession(false)){CartMapper carts=s.getMapper(CartMapper.class);OrderMapper orders=s.getMapper(OrderMapper.class);List<CartLine> lines=carts.findByUserForUpdate(userId);if(lines.isEmpty())throw new IllegalStateException("장바구니가 비어 있습니다.");BigDecimal total=BigDecimal.ZERO;for(CartLine line:lines){if(line.getQuantity()>line.getStock())throw new IllegalStateException(line.getName()+"의 재고가 부족합니다.");total=total.add(line.getSubtotal());}String number="MRW-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);orders.insertOrder(userId,number,total);Long orderId=orders.findIdByNumber(number);for(CartLine line:lines){if(orders.decreaseStock(line.getProductId(),line.getQuantity())!=1)throw new IllegalStateException("결제 중 재고가 변경되었습니다.");orders.insertItem(orderId,line);}carts.clear(userId);s.commit();return number;}catch(RuntimeException e){throw e;}}
 public List<OrderSummary> getOrders(long userId){try(SqlSession s=MyBatisProvider.getFactory().openSession()){return s.getMapper(OrderMapper.class).findByUser(userId);}}
}
